package com.acid.camera;
import android.hardware.camera2.*;import android.hardware.camera2.params.*;import android.graphics.ImageFormat;import android.util.Size;import java.util.*;
/** Enumerates every publicly advertised ID, regardless of JPEG availability. */
class DeviceProbe {
 static final ArrayList<String> lastErrors=new ArrayList<>();
 static class Entry {String parent,physical,label;CameraCharacteristics c;int format;Entry(String p,String ph,CameraCharacteristics c){parent=p;physical=ph;this.c=c;Integer pattern=c.get(CameraCharacteristics.SENSOR_INFO_COLOR_FILTER_ARRANGEMENT);boolean depth=has(c,CameraCharacteristics.REQUEST_AVAILABLE_CAPABILITIES_DEPTH_OUTPUT);label=p+(ph==null?"":" / physical "+ph)+" · "+(pattern!=null&&pattern==6?"NEAR-INFRARED":pattern!=null&&pattern==5?"MONOCHROME":"COLOR / unspecified")+(depth?" + DEPTH":"");StreamConfigurationMap m=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);format=0;if(m!=null){int[] formats=m.getOutputFormats();for(int f:formats)if(f==ImageFormat.DEPTH16)format=f;if(format==0&&pattern!=null&&(pattern==5||pattern==6))for(int f:formats)if(f==ImageFormat.Y8||f==ImageFormat.YUV_420_888)format=f;}}}
 static boolean has(CameraCharacteristics c,int value){int[] caps=c.get(CameraCharacteristics.REQUEST_AVAILABLE_CAPABILITIES);if(caps!=null)for(int v:caps)if(v==value)return true;return false;}
 static ArrayList<Entry> entries(CameraManager manager){ArrayList<Entry> out=new ArrayList<>();lastErrors.clear();try{for(String id:manager.getCameraIdList()){try{CameraCharacteristics c=manager.getCameraCharacteristics(id);out.add(new Entry(id,null,c));for(String physical:c.getPhysicalCameraIds())try{out.add(new Entry(id,physical,manager.getCameraCharacteristics(physical)));}catch(Exception error){lastErrors.add("Physical "+physical+": "+error);}}catch(Exception error){lastErrors.add("Camera "+id+": "+error);}}}catch(Exception error){lastErrors.add("Camera list: "+error);}return out;}
 static String format(int f){if(f==ImageFormat.JPEG)return "JPEG";if(f==ImageFormat.YUV_420_888)return "YUV_420_888";if(f==ImageFormat.Y8)return "Y8";if(f==ImageFormat.DEPTH16)return "DEPTH16";if(f==ImageFormat.DEPTH_POINT_CLOUD)return "DEPTH_POINT_CLOUD";if(f==ImageFormat.RAW_SENSOR)return "RAW_SENSOR";if(f==ImageFormat.PRIVATE)return "PRIVATE";return "format "+f;}
 static String report(CameraManager manager){StringBuilder b=new StringBuilder("Every advertised Camera2 ID is inspected; JPEG is not required. No numeric hidden-ID guessing. Devices not exposed to this app cannot be proved absent. Thermal cameras using vendor SDKs/USB protocols may not appear.\n");ArrayList<Entry> entries=entries(manager);b.append("Entries: "+entries.size()+"\n");for(String error:lastErrors)b.append("DISCOVERY ERROR: "+error+"\n");try{if(android.os.Build.VERSION.SDK_INT>=30)b.append("Concurrent groups: "+manager.getConcurrentCameraIds()+"\n");}catch(Exception e){b.append(e+"\n");}for(Entry e:entries){b.append("\n"+e.label+"\nCapabilities: "+Arrays.toString(e.c.get(CameraCharacteristics.REQUEST_AVAILABLE_CAPABILITIES))+"\nPhysical IDs: "+e.c.getPhysicalCameraIds()+"\nSensor Lab viewer: "+(e.format==0?"not an exposed supported NIR/mono/depth stream":format(e.format))+"\n");StreamConfigurationMap m=e.c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);if(m!=null)for(int f:m.getOutputFormats()){b.append(format(f)+": "+Arrays.toString(m.getOutputSizes(f))+"\n");}else b.append("No standard stream map\n");}return b.toString();}
}
